using System;using System.Linq;using System.Collections.Generic;using System.Runtime.CompilerServices;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class DropdownCellClipboard {
 static readonly ConditionalWeakTable<DataGridView,object> attached=new ConditionalWeakTable<DataGridView,object>();
 static bool Profile(DataGridViewCell cell){return cell is DataGridViewComboBoxCell&&cell.OwningColumn!=null&&cell.OwningColumn.HeaderText.IndexOf("profile",StringComparison.OrdinalIgnoreCase)>=0;}
 internal static bool Process(WorksDataGridView grid,Keys keys){if(!Profile(grid.CurrentCell))return false;if(keys==(Keys.Control|Keys.C)){try{string value=Convert.ToString(grid.CurrentCell.Value);if(value!="")Clipboard.SetText(value);}catch(System.Runtime.InteropServices.ExternalException){}return true;}if(keys!=(Keys.Control|Keys.V))return false;try{Paste(grid);}catch(Exception ex){MessageBox.Show(grid.FindForm(),ex.Message,"Paste handbook profile",MessageBoxButtons.OK,MessageBoxIcon.Information);}return true;}
 internal static void Paste(WorksDataGridView grid){if(grid.ReadOnly||grid.CurrentCell==null||grid.CurrentCell.ReadOnly||!Clipboard.ContainsText())return;string text=Clipboard.GetText().Trim();if(text=="")return;var cells=grid.SelectedCells.Cast<DataGridViewCell>().Where(c=>Profile(c)&&!c.ReadOnly).OrderBy(c=>c.RowIndex).ToList();if(cells.Count==0)cells.Add(grid.CurrentCell);if(text.Contains("\t")||text.Contains("\n")||text.Contains("\r"))throw new Exception("Copy one handbook profile name, then select its target profile cell(s).");foreach(var cell in cells){var combo=(DataGridViewComboBoxCell)cell;if(!combo.Items.Cast<object>().Any(item=>Convert.ToString(item).Equals(text,StringComparison.OrdinalIgnoreCase)))throw new Exception("The copied profile is not available in a target dropdown. Choose the matching profile family first.");}grid.EndEdit();var changed=cells.Where(c=>!Convert.ToString(c.Value).Equals(text,StringComparison.OrdinalIgnoreCase)).ToList();if(changed.Count==0)return;grid.CurrentCell=changed[0];grid.ApplyProfilePaste(()=>{foreach(var cell in changed){var target=cell.OwningRow.IsNewRow?grid.Rows[grid.Rows.Add()].Cells[cell.ColumnIndex]:cell;var combo=(DataGridViewComboBoxCell)target;target.Value=combo.Items.Cast<object>().First(item=>Convert.ToString(item).Equals(text,StringComparison.OrdinalIgnoreCase));if(cell==changed[0])grid.CurrentCell=target;}});}
 internal static void Attach(DataGridView grid){object marker;if(attached.TryGetValue(grid,out marker))return;attached.Add(grid,new object());Action menu=()=>{var context=grid.ContextMenuStrip;if(context==null||context.Items.Cast<ToolStripItem>().Any(i=>object.Equals(i.Tag,"profile-copy")))return;var copy=new ToolStripMenuItem("Copy profile (Ctrl+C)"){Tag="profile-copy"};var paste=new ToolStripMenuItem("Paste profile (Ctrl+V)"){Tag="profile-paste"};copy.Click+=(s,e)=>{var works=grid as WorksDataGridView;if(works!=null)Process(works,Keys.Control|Keys.C);};paste.Click+=(s,e)=>{var works=grid as WorksDataGridView;if(works!=null)Process(works,Keys.Control|Keys.V);};context.Items.Add(copy);context.Items.Add(paste);context.Opening+=(s,e)=>{copy.Visible=paste.Visible=Profile(grid.CurrentCell);paste.Enabled=grid.CurrentCell!=null&&!grid.CurrentCell.ReadOnly&&!grid.ReadOnly;};};grid.ContextMenuStripChanged+=(s,e)=>menu();menu();KeyEventHandler handler=(s,e)=>{var works=grid as WorksDataGridView;if(works!=null&&(e.KeyData==(Keys.Control|Keys.C)||e.KeyData==(Keys.Control|Keys.V))&&Process(works,e.KeyData))e.Handled=e.SuppressKeyPress=true;};Control editor=null;grid.EditingControlShowing+=(s,e)=>{if(editor!=null)editor.KeyDown-=handler;editor=e.Control;editor.KeyDown+=handler;};}
}
}
